			switch (diagramType) {
				case "flowchart": return flowchartAssembler;
				case "classDiagram": return classAssembler;
				case "erDiagram": return erAssembler;
				default: throw new Error(`Assembler: getAssembler unsupported diagramType '${diagramType}'`);
			}
